function customQueryLabels(httpClient: HttpClient) {
  const router = /*#__PURE__*/ createQueryOverloadRouter({
    builderQueryFunction: (options?: QueryLabelsOptions) =>
      publicQueryLabels(httpClient)(options),
    typedQueryFunction: (
      query: ContactLabelQuery,
      options?: QueryLabelsOptions
    ) => publicTypedQueryLabels(httpClient)(query, options),
    hasOptionsParameter: true,
  });

  function overloadedQuery(
    query: ContactLabelQuery,
    options?: QueryLabelsOptions
  ): ReturnType<typeof universalTypedQueryLabels>;
  function overloadedQuery(options?: QueryLabelsOptions): LabelsQueryBuilder;
  function overloadedQuery(
    queryOrOptions?: ContactLabelQuery | QueryLabelsOptions,
    options?: QueryLabelsOptions
  ): any {
    return router(...arguments);
  }

  return overloadedQuery;
}

